using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;using Frociart;
internal static class FileEditorTests {
 const BindingFlags Flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static int checks;static string root;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);checks++;Console.WriteLine("PASS "+why);}
 static T Field<T>(object owner,string name){return(T)owner.GetType().GetField(name,Flags).GetValue(owner);}
 static object Call(object owner,string name,params object[] args){return owner.GetType().GetMethod(name,Flags).Invoke(owner,args);}
 static void Pump(){var end=DateTime.UtcNow.AddMilliseconds(90);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<end);}
 static void Show(Form f){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-3000);f.Show();Pump();}
 static IEnumerable<Control> Desc(Control c){foreach(Control child in c.Controls){yield return child;foreach(var other in Desc(child))yield return other;}}
 static void Shot(Form f,string name){using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,name+".png"));}}
 static void Editors(){foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);
  using(var d=new FileEditorDialog(NodeKind.OpenFile,"LETTURA \"dati.txt\"",null)){Show(d);Check(d.Channel.SelectedIndex==0&&d.Value.Text=="\"dati.txt\"","Open separates read channel from file expression");d.Channel.SelectedIndex=1;d.Value.Text="\"copia.txt\"";d.Apply.PerformClick();Check(d.Result=="SCRITTURA \"copia.txt\""&&d.DialogResult==DialogResult.OK,"Guided open commits selected channel and expression");}
  using(var d=new FileEditorDialog(NodeKind.ReadFile,"righe[2]",null)){Show(d);d.Value.Text="riga + 1";d.Apply.PerformClick();Check(d.Visible&&d.Result==null&&d.Error.Text.Length>0&&d.Value.Text=="riga + 1","Invalid read target preserves input and keeps editor open");d.Value.Text="righe[2]";d.Apply.PerformClick();Check(d.Result=="righe[2]","Corrected vector target is accepted");}
  using(var d=new FileEditorDialog(NodeKind.WriteFile,"SENZA_A_CAPO \"  è 🦊  \"",null)){d.Size=d.MinimumSize;Show(d);Check(!d.Newline.Checked&&d.Value.Text=="\"  è 🦊  \"","Write preserves quoted whitespace and Unicode");d.Newline.Checked=true;d.PerformLayout();Shot(d,dark?"write-dark-minimum":"write-light-minimum");Check(d.Apply.Width>=100&&d.Apply.Parent.Width>d.Apply.Width&&d.RectangleToClient(d.Apply.RectangleToScreen(d.Apply.ClientRectangle)).Bottom<=d.ClientSize.Height,"Narrow dialog keeps separate action buttons");d.Apply.PerformClick();Check(d.Result=="\"  è 🦊  \"","Newline toggle changes option without changing literal");}
  using(var d=new FileEditorDialog(NodeKind.CloseFile,"SCRITTURA",null)){Show(d);Check(d.Channel.SelectedIndex==1&&!Desc(d).OfType<TextBox>().Any(t=>t.Visible),"Close needs only a channel");d.Channel.SelectedIndex=0;d.Apply.PerformClick();Check(d.Result=="LETTURA","Close commits read channel");}
 }
 using(var d=new FileEditorDialog(NodeKind.OpenFile,"NOT_A_CHANNEL \"draft\"",null)){Show(d);Check(d.Value.Text=="NOT_A_CHANNEL \"draft\""&&d.Error.Text.Length>0,"Malformed draft remains available for correction");d.Close();Check(d.Result==null,"Cancel cannot invent a replacement instruction");}
 using(var d=new FileEditorDialog(NodeKind.OpenFile,"LETTURA \"x\"",null)){Show(d);d.Value.Text="\""+new string('a',8188)+"\"";d.Apply.PerformClick();Check(d.Result==null&&d.Error.Text.Contains("8192")&&d.Value.Text.Length==8190,"Whole instruction limit includes channel without truncating typed text");d.Value.Text="\"fixed\"";d.Apply.PerformClick();Check(d.Result=="LETTURA \"fixed\"","Oversized instruction can be corrected");}
 using(var library=new FunctionLibraryDialog()){Show(library);library.Search.Text="EOF";Check(library.Results.Items.Count==1&&library.Details.Text.Contains("lettura"),"EOF catalog explains required read context");library.Insert.PerformClick();Check(library.SelectedExample=="non EOF()","EOF inserts loop guard");}
 }
 static void Menus(MainForm f){f.SetDocument(FlowPseudocode.Decode("STAMPA 1"),null,false);f.EnterEditor();Pump();
  var group=Desc(f).OfType<FlowButton>().Single(b=>b.Name=="FilePaletteGroup");Check(!Desc(f).Any(c=>c.Name=="FilePaletteOpenFile"),"File palette starts collapsed");group.PerformClick();Pump();
  foreach(NodeKind kind in FileBlocks.Kinds){var b=Desc(f).OfType<BlockButton>().Single(c=>c.Name=="FilePalette"+kind);int count=f.Document.Nodes.Count;Call(b,"OnClick",EventArgs.Empty);Pump();Check(f.Document.Nodes.Count==count+1&&f.Document.Nodes.Last().Kind==kind,"Palette creates real "+kind);Compiler.Block(f.Document.Nodes.Last());}
  var open=f.Document.Nodes.First(n=>n.Kind==NodeKind.OpenFile);f.Canvas.SelectNode(open.Id);Pump();var edit=Field<FlowButton>(f,"functionButton");Check(edit.Visible&&edit.Text=="Imposta il file…","Actual inspector exposes file settings");
  Exception failure=null;using(var timer=new System.Windows.Forms.Timer{Interval=40}){timer.Tick+=delegate{var d=Application.OpenForms.OfType<FileEditorDialog>().FirstOrDefault();if(d==null)return;timer.Stop();try{d.Channel.SelectedIndex=1;d.Value.Text="\"guided.txt\"";d.Apply.PerformClick();}catch(Exception ex){failure=ex;d.Close();}};timer.Start();edit.PerformClick();}if(failure!=null)throw failure;Check(open.Text=="SCRITTURA \"guided.txt\"","Guided inspector applies to selected graph node");
  using(var picker=new BlockPicker()){var files=picker.Items.OfType<ToolStripMenuItem>().Single(i=>i.Name=="FileBlockGroup");Check(files.DropDownItems.Count==4,"Connection menu groups all four file actions");foreach(ToolStripItem item in files.DropDownItems){NodeKind? selected=null;EventHandler<BlockKindEventArgs> handler=(s,e)=>selected=e.Kind;picker.KindSelected+=handler;item.PerformClick();picker.KindSelected-=handler;Check(selected==(NodeKind)item.Tag,"Connection submenu dispatches "+item.Tag);}}
  Shot(f,"file-palette");f.SetDocument(new Diagram(),null,false);
 }
 static void Example(){foreach(string input in new[]{"","alpha\r\n\r\n è 🦊 \n","last line"})foreach(int pass in new[]{0,1,2}){var doc=Examples.CopyFile();if(pass==1)doc=FlowPseudocode.Decode(FlowPseudocode.Encode(doc));if(pass==2)doc=DiagramIO.Clone(doc);Check(!Validator.Validate(doc).Any(i=>i.Severity==Severity.Error),"Copy example validates, pass "+pass);var r=new Interpreter(doc);int reads=0,saves=0;string saved=null;for(int i=0;i<300&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++){if(r.State==RuntimeState.WaitingForFile){var request=r.PendingFile;if(request.Kind==FlowFileRequestKind.Read){reads++;r.ProvideFile(request,input);}else{saves++;saved=request.Text;r.ProvideFile(request);}}else r.Step();}Check(r.State==RuntimeState.Completed,"Copy example completes: "+r.Error);int expected=input.Length==0?0:input=="last line"?1:3;string text=input.Length==0?"":input=="last line"?"last line\n":"alpha\n\n è 🦊 \n";Check(reads==1&&saves==1&&saved==text&&String.Join("",r.Output)=="Righe copiate: "+expected,"Example copies exact content, blank lines and count");}}
 [STAThread]static int Main(){try{root=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"file-editors");Directory.CreateDirectory(root);Application.EnableVisualStyles();Editors();Example();Exception failure=null;using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-3000);f.Shown+=delegate{f.BeginInvoke(new Action(delegate{try{Menus(f);}catch(Exception ex){failure=ex;}finally{f.Close();}}));};Application.Run(f);}if(failure!=null)throw failure;Console.WriteLine("FILE_EDITORS_PASS checks="+checks);return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
